import { latestAdviceStatus } from './portfolio-ledger';
import { buildAdviceAuditRecord, type AdviceResult } from './rebalance';
import type { AssetCode, LocalAdviceRecord, LocalPortfolio, PublicSnapshot } from './types';

export type HouseholdOperationAction = 'NONE' | 'OPEN_HOLDINGS' | 'ENTER_PREMIUM' | 'REVIEW_ADVICE' | 'RECORD_EXECUTION' | 'COMPLETE_REVIEW';
export type HouseholdOperationStatus = 'DONE' | 'CURRENT' | 'WAITING' | 'BLOCKED';
export type HouseholdWorkflowState = 'DATA_BLOCKED' | 'NEED_RECORDS' | 'PLAN_PREVIEW' | 'PREMIUM_INPUT' | 'PLAN_READY' | 'NO_ACTION_READY' | 'EXECUTION_PENDING' | 'EXECUTION_PARTIAL' | 'CLOSE_READY' | 'MONTH_COMPLETE';

export interface HouseholdOperationStep {
  key: 'RECORDS' | 'PLAN' | 'EXECUTION' | 'CLOSE';
  label: string;
  detail: string;
  status: HouseholdOperationStatus;
  action: HouseholdOperationAction;
}

export interface HouseholdOperationState {
  month: string;
  completed: number;
  total: number;
  steps: HouseholdOperationStep[];
  current: HouseholdOperationStep;
  adviceRecord?: LocalAdviceRecord;
  workflowState: HouseholdWorkflowState;
  dataGate: { passed: boolean; detail: string };
  premiumCode?: AssetCode;
}

function latestActiveSnapshotId(portfolio: LocalPortfolio): string | null {
  return [...(portfolio.snapshots ?? [])]
    .filter((item) => !item.supersededBy)
    .sort((left, right) => left.createdAt.localeCompare(right.createdAt))
    .at(-1)?.id ?? null;
}

export function deriveHouseholdOperation(
  snapshot: PublicSnapshot,
  portfolio: LocalPortfolio,
  advice: AdviceResult,
): HouseholdOperationState {
  const month = snapshot.meta.confirmedSignalDate.slice(0, 7);
  const activeRows = advice.rows.filter((row) => row.action !== 'NO TRADE');
  const snapshotId = latestActiveSnapshotId(portfolio);
  let expectedAdviceId = '';
  try { expectedAdviceId = advice.adviceAllowed ? buildAdviceAuditRecord(portfolio, snapshot, advice).record.adviceId : ''; } catch { expectedAdviceId = ''; }
  const records = [...(portfolio.adviceRecords ?? [])].reverse();
  const continuingRecord = records.find((record) => {
    const status = latestAdviceStatus(portfolio, record.adviceId)?.status ?? record.status;
    return !record.supersededBy
      && record.signalDate === snapshot.meta.confirmedSignalDate
      && ['PARTIAL', 'EXECUTED', 'SKIPPED', 'EXPIRED'].includes(status);
  });
  const adviceRecord = continuingRecord
    ?? records.find((record) => record.adviceId === expectedAdviceId && !record.supersededBy)
    ?? records.find((record) => !record.executionInputFingerprint
      && record.signalDate === snapshot.meta.confirmedSignalDate
      && record.holdingsSnapshotId === snapshotId
      && !record.supersededBy);
  const adviceStatus = adviceRecord
    ? latestAdviceStatus(portfolio, adviceRecord.adviceId)?.status ?? adviceRecord.status
    : undefined;
  const executionDone = adviceStatus === 'EXECUTED'
    || adviceStatus === 'SKIPPED'
    || adviceStatus === 'EXPIRED';
  const completedReview = (portfolio.monthlyReviews ?? []).some((review) => review.month === month);
  const missingPremiumCode = (Object.entries(advice.premiumRequiredByCode) as Array<[AssetCode, boolean]>)
    .find(([code, required]) => required && portfolio.qdiiPremiums?.[code] == null)?.[0];
  const recordsDone = advice.available && advice.holdingsFresh;
  let workflowState: HouseholdWorkflowState;
  if (snapshot.health.blocking) workflowState = 'DATA_BLOCKED';
  else if (!recordsDone) workflowState = 'NEED_RECORDS';
  else if (completedReview) workflowState = 'MONTH_COMPLETE';
  else if (missingPremiumCode && !adviceRecord) workflowState = 'PREMIUM_INPUT';
  else if (!adviceRecord) workflowState = activeRows.length ? 'PLAN_READY' : 'NO_ACTION_READY';
  else if (adviceStatus === 'PARTIAL') workflowState = 'EXECUTION_PARTIAL';
  else if (executionDone || activeRows.length === 0) workflowState = 'CLOSE_READY';
  else workflowState = 'EXECUTION_PENDING';

  const recordsDetail = snapshot.health.blocking
    ? snapshot.health.summary
    : !advice.available ? '首次建立持仓、可选成本和组合内现金'
      : advice.holdingsFresh ? `真实记录更新于 ${portfolio.updatedAt.slice(0, 10)}` : '真实记录已过期，需要核对份额和现金';
  const planDetail = missingPremiumCode && !adviceRecord
    ? `${missingPremiumCode} 存在计划新增，先补齐或接受缺失溢价门控`
    : adviceRecord ? '本月计划已经只追加保存' : activeRows.length ? `${activeRows.length}只 ETF 需要家庭复核` : '全部资产位于免交易带，保存无需操作结论';
  const executionDetail = activeRows.length === 0
    ? '本月无需成交登记'
    : adviceStatus === 'PARTIAL' ? '已登记部分成交，继续登记或结束剩余计划'
      : executionDone ? `实际结果：${adviceStatus}` : adviceRecord ? '等待登记真实成交或跳过决定' : '保存本月计划后开放';
  const closeDetail = completedReview ? '月度证据已经封存，只读保留' : workflowState === 'CLOSE_READY' ? '核对证据并完成本月记录' : '等待实际结果形成';
  const definitions: Array<Omit<HouseholdOperationStep, 'status'> & { done: boolean }> = [
    {
      key: 'RECORDS', label: '更新真实记录', action: 'OPEN_HOLDINGS', detail: recordsDetail,
      done: recordsDone || completedReview,
    },
    {
      key: 'PLAN', label: '核对本月计划', action: missingPremiumCode ? 'ENTER_PREMIUM' : 'REVIEW_ADVICE',
      detail: planDetail, done: Boolean(adviceRecord) || completedReview,
    },
    {
      key: 'EXECUTION', label: '登记实际结果', action: 'RECORD_EXECUTION', detail: executionDetail,
      done: completedReview || (Boolean(adviceRecord) && (activeRows.length === 0 || executionDone)),
    },
    {
      key: 'CLOSE', label: '关闭本月', action: 'COMPLETE_REVIEW', detail: closeDetail,
      done: completedReview,
    },
  ];
  let waiting = false;
  const steps = definitions.map((definition): HouseholdOperationStep => {
    let status: HouseholdOperationStatus;
    if (definition.done) status = 'DONE';
    else if (!waiting) {
      status = definition.key === 'RECORDS' && snapshot.health.blocking ? 'BLOCKED' : 'CURRENT';
      waiting = true;
    } else status = 'WAITING';
    return { ...definition, status };
  });
  const current = steps.find((step) => step.status === 'CURRENT' || step.status === 'BLOCKED') ?? {
    key: 'CLOSE', label: '本月流程已完成', detail: '维持组合并等待下一次月末确认', status: 'DONE', action: 'NONE',
  };
  return {
    month, completed: steps.filter((step) => step.status === 'DONE').length, total: steps.length,
    steps, current, adviceRecord, workflowState,
    dataGate: { passed: !snapshot.health.blocking, detail: snapshot.health.blocking ? snapshot.health.summary : `${snapshot.meta.signalDate} 数据健康；${snapshot.meta.confirmedSignalDate} 月末信号已确认` },
    premiumCode: missingPremiumCode,
  };
}

export interface ExecutionVarianceRow {
  code: AssetCode;
  plannedAmount: number;
  actualAmount: number;
  difference: number;
  actualFee: number;
}

export interface ExecutionVarianceSummary {
  available: boolean;
  plannedNotional: number;
  actualNotional: number;
  completionRate: number | null;
  plannedFees: number;
  actualFees: number;
  feeDifference: number;
  maximumTargetDeviation: number | null;
  rows: ExecutionVarianceRow[];
}

export function summarizeExecutionVariance(
  portfolio: LocalPortfolio,
  record: LocalAdviceRecord,
): ExecutionVarianceSummary {
  const reports = (portfolio.executionReports ?? []).filter((report) => report.adviceId === record.adviceId);
  const codes = new Set<AssetCode>([
    ...Object.keys(record.plannedAmounts ?? {}) as AssetCode[],
    ...reports.flatMap((report) => report.fills.map((fill) => fill.code)),
  ]);
  const rows = [...codes].map((code): ExecutionVarianceRow => {
    const plannedAmount = record.plannedAmounts?.[code] ?? 0;
    const fills = reports.flatMap((report) => report.fills).filter((fill) => fill.code === code);
    const actualAmount = fills.reduce((sum, fill) => sum + fill.shares * fill.price * (fill.side === 'BUY' ? 1 : -1), 0);
    const actualFee = fills.reduce((sum, fill) => sum + fill.fee, 0);
    return { code, plannedAmount, actualAmount, difference: actualAmount - plannedAmount, actualFee };
  });
  const plannedNotional = rows.reduce((sum, row) => sum + Math.abs(row.plannedAmount), 0);
  const actualNotional = rows.reduce((sum, row) => sum + Math.abs(row.actualAmount), 0);
  const plannedFees = Object.values(record.plannedEstimatedCosts ?? {}).reduce((sum, value) => sum + (value ?? 0), 0);
  const actualFees = rows.reduce((sum, row) => sum + row.actualFee, 0);
  const lastReport = [...reports].sort((left, right) => left.createdAt.localeCompare(right.createdAt)).at(-1);
  const postSnapshot = lastReport
    ? (portfolio.snapshots ?? []).find((item) => item.id === lastReport.postTradeSnapshotId)
    : undefined;
  const deviations = postSnapshot && postSnapshot.totalAssets > 0
    ? Object.entries(record.householdTargets).map(([rawCode, target]) => {
      const code = rawCode as AssetCode;
      return Math.abs((postSnapshot.values[code] ?? 0) / postSnapshot.totalAssets - (target ?? 0));
    })
    : [];
  return {
    available: Boolean(record.plannedAmounts),
    plannedNotional,
    actualNotional,
    completionRate: plannedNotional > 0 ? actualNotional / plannedNotional : null,
    plannedFees,
    actualFees,
    feeDifference: actualFees - plannedFees,
    maximumTargetDeviation: deviations.length ? Math.max(...deviations) : null,
    rows: rows.sort((left, right) => Math.abs(right.plannedAmount) - Math.abs(left.plannedAmount)),
  };
}
