import type { MarketSeriesBundle, PublicationObservation, PublicBundlePointer, PublicSnapshot } from './types';

export interface PublicResources {
  snapshot: PublicSnapshot;
  marketSeries?: MarketSeriesBundle;
  modelSource?: string;
  buildId: string;
  source: 'ATOMIC' | 'LEGACY' | 'LAST_COMPLETE';
}

const CACHE_DATABASE = 'hams-public-bundle-cache';
const CACHE_STORE = 'bundle';
const OBSERVATION_STORE = 'publication-observations';
const CACHE_KEY = 'last-complete';
const CACHE_VERSION = 2;

async function fetchJson<T>(url: string, cache: RequestCache = 'default'): Promise<T> {
  const response = await fetch(url, { cache });
  if (!response.ok) throw new Error(`公开数据读取失败（HTTP ${response.status}）`);
  return await response.json() as T;
}

function assertBuildId(expected: string, label: string, actual?: string | null): void {
  if (actual && actual !== expected) throw new Error(`${label}批次不一致：${actual} ≠ ${expected}`);
}

export async function loadNetworkResources(
  root: string,
  options: { market: boolean; model: boolean },
): Promise<PublicResources> {
  let pointer: PublicBundlePointer | null = null;
  try {
    pointer = await fetchJson<PublicBundlePointer>(`${root}data/latest.json?t=${Date.now()}`, 'no-store');
  } catch {
    pointer = null;
  }
  if (pointer?.schemaVersion === '1.0' && pointer.buildId && pointer.basePath) {
    const base = `${root}data/${pointer.basePath}`;
    const [snapshot, health, marketSeries, modelSource, publicationStatus] = await Promise.all([
      fetchJson<PublicSnapshot>(`${base}snapshot.json`, 'force-cache'),
      fetchJson<PublicSnapshot['health'] & { buildId?: string }>(`${base}health.json`, 'force-cache'),
      options.market ? fetchJson<MarketSeriesBundle>(`${base}market-series.json`, 'force-cache') : Promise.resolve(undefined),
      options.model ? fetch(`${base}risk-control-models.md`, { cache: 'force-cache' }).then(async (response) => {
        if (!response.ok) throw new Error('风控模型文档读取失败');
        return await response.text();
      }) : Promise.resolve(undefined),
      fetchJson<PublicSnapshot['health'] & { generatedAt?: string; lastCompleteBuildId?: string }>(`${root}data/publication-status.json?t=${Date.now()}`, 'no-store').catch(() => null),
    ]);
    assertBuildId(pointer.buildId, '风险快照', snapshot.meta.buildId);
    assertBuildId(pointer.buildId, '健康检查', health.buildId);
    assertBuildId(pointer.buildId, '行情序列', marketSeries?.buildId);
    snapshot.health = health;
    if (publicationStatus?.blocking
      && publicationStatus.lastCompleteBuildId === pointer.buildId
      && (publicationStatus.generatedAt ?? '') > snapshot.meta.generatedAt) {
      snapshot.health = {
        status: 'DATA ERROR', blocking: true,
        summary: `${publicationStatus.summary}；当前保留上次完整数据包，只读且不生成新建议`,
        issues: publicationStatus.issues,
      };
    }
    return { snapshot, marketSeries, modelSource, buildId: pointer.buildId, source: 'ATOMIC' };
  }

  // Compatibility path for a V5.0 deployment before latest.json exists.
  const [snapshot, health, marketSeries, modelSource] = await Promise.all([
    fetchJson<PublicSnapshot>(`${root}data/snapshot.json?t=${Date.now()}`, 'no-store'),
    fetchJson<PublicSnapshot['health'] & { generatedAt?: string }>(`${root}data/health.json?t=${Date.now()}`, 'no-store').catch(() => null),
    options.market ? fetchJson<MarketSeriesBundle>(`${root}data/market-series.json?t=${Date.now()}`, 'no-store') : Promise.resolve(undefined),
    options.model ? fetch(`${root}data/risk-control-models.md?t=${Date.now()}`, { cache: 'no-store' }).then(async (response) => {
      if (!response.ok) throw new Error('风控模型文档读取失败');
      return await response.text();
    }) : Promise.resolve(undefined),
  ]);
  if (health?.generatedAt && health.generatedAt >= snapshot.meta.generatedAt) snapshot.health = health;
  return { snapshot, marketSeries, modelSource, buildId: snapshot.meta.buildId ?? `legacy-${snapshot.meta.generatedAt}`, source: 'LEGACY' };
}

function openCache(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(CACHE_DATABASE, CACHE_VERSION);
    request.onupgradeneeded = () => {
      if (!request.result.objectStoreNames.contains(CACHE_STORE)) request.result.createObjectStore(CACHE_STORE);
      if (!request.result.objectStoreNames.contains(OBSERVATION_STORE)) request.result.createObjectStore(OBSERVATION_STORE);
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

export async function saveLastCompleteBundle(resources: PublicResources): Promise<void> {
  if (resources.snapshot.health.blocking) return;
  const existing = await loadLastCompleteBundle().catch(() => null);
  const merged: PublicResources = existing?.buildId === resources.buildId ? {
    ...resources,
    marketSeries: resources.marketSeries ?? existing.marketSeries,
    modelSource: resources.modelSource ?? existing.modelSource,
    source: resources.source,
  } : resources;
  try {
    const database = await openCache();
    await new Promise<void>((resolve, reject) => {
      const request = database.transaction(CACHE_STORE, 'readwrite').objectStore(CACHE_STORE).put(merged, CACHE_KEY);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
    database.close();
  } catch {
    // Public data is deliberately separate from the private portfolio backup.
    localStorage.setItem(CACHE_DATABASE, JSON.stringify(merged));
  }
}

export async function loadLastCompleteBundle(): Promise<PublicResources | null> {
  try {
    const database = await openCache();
    const value = await new Promise<PublicResources | undefined>((resolve, reject) => {
      const request = database.transaction(CACHE_STORE).objectStore(CACHE_STORE).get(CACHE_KEY);
      request.onsuccess = () => resolve(request.result as PublicResources | undefined);
      request.onerror = () => reject(request.error);
    });
    database.close();
    return value ? { ...value, source: 'LAST_COMPLETE' } : null;
  } catch {
    const raw = localStorage.getItem(CACHE_DATABASE);
    return raw ? { ...(JSON.parse(raw) as PublicResources), source: 'LAST_COMPLETE' } : null;
  }
}

function loadFallbackObservations(): PublicationObservation[] {
  try {
    if (typeof localStorage === 'undefined') return [];
    const raw = localStorage.getItem(`${CACHE_DATABASE}:observations`);
    return raw ? JSON.parse(raw) as PublicationObservation[] : [];
  } catch {
    return [];
  }
}

export async function loadPublicationObservations(): Promise<PublicationObservation[]> {
  try {
    const database = await openCache();
    const observations = await new Promise<PublicationObservation[]>((resolve, reject) => {
      const request = database.transaction(OBSERVATION_STORE).objectStore(OBSERVATION_STORE).getAll();
      request.onsuccess = () => resolve(request.result as PublicationObservation[]);
      request.onerror = () => reject(request.error);
    });
    database.close();
    return observations.sort((left, right) => right.observedAt.localeCompare(left.observedAt)).slice(0, 30);
  } catch {
    return loadFallbackObservations().sort((left, right) => right.observedAt.localeCompare(left.observedAt)).slice(0, 30);
  }
}

export async function recordPublicationObservation(
  resources: PublicResources,
  observedAt = new Date().toISOString(),
): Promise<PublicationObservation[]> {
  const summary = resources.snapshot.health.summary;
  const observation: PublicationObservation = {
    id: `${resources.buildId}:${resources.snapshot.health.blocking ? 'BLOCKED' : 'OK'}:${summary}`,
    buildId: resources.buildId,
    generatedAt: resources.snapshot.meta.generatedAt,
    observedAt,
    productVersion: resources.snapshot.meta.webVersion,
    sourceCommit: resources.snapshot.meta.sourceCommit ?? 'unknown',
    source: resources.source,
    status: resources.snapshot.health.status,
    blocking: resources.snapshot.health.blocking,
    summary,
  };
  try {
    const database = await openCache();
    await new Promise<void>((resolve, reject) => {
      const request = database.transaction(OBSERVATION_STORE, 'readwrite').objectStore(OBSERVATION_STORE).put(observation, observation.id);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
    database.close();
  } catch {
    const existing = loadFallbackObservations();
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem(`${CACHE_DATABASE}:observations`, JSON.stringify([
        ...existing.filter((item) => item.id !== observation.id), observation,
      ].slice(-30)));
    }
  }
  return loadPublicationObservations();
}
