import type { HoldingImportReceipt, LocalPortfolio, RecoveryPoint } from './types';
import { createEmptyPortfolio, migratePortfolio } from './portfolio-ledger';

const DATABASE = 'hams-v4-private';
const LEGACY_DATABASE = 'fraiss-v3-private';
const STORE = 'portfolio';
const RECOVERY_STORE = 'recovery-points';
const DRAFT_STORE = 'workflow-drafts';
const KEY = 'current';
const RECEIPTS_KEY = 'holding-import-receipts';
const DATABASE_VERSION = 3;

export interface WorkflowDraft {
  id: string;
  stage: string;
  values: Record<string, string>;
  updatedAt: string;
  evidenceFingerprint: string;
}

function openDatabase(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DATABASE, DATABASE_VERSION);
    request.onupgradeneeded = () => {
      if (!request.result.objectStoreNames.contains(STORE)) request.result.createObjectStore(STORE);
      if (!request.result.objectStoreNames.contains(RECOVERY_STORE)) request.result.createObjectStore(RECOVERY_STORE);
      if (!request.result.objectStoreNames.contains(DRAFT_STORE)) request.result.createObjectStore(DRAFT_STORE);
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function readDatabase(name: string): Promise<LocalPortfolio | undefined> {
  return new Promise((resolve, reject) => {
    const request = name === DATABASE ? indexedDB.open(name, DATABASE_VERSION) : indexedDB.open(name);
    request.onupgradeneeded = () => {
      if (!request.result.objectStoreNames.contains(STORE)) request.result.createObjectStore(STORE);
      if (name === DATABASE && !request.result.objectStoreNames.contains(RECOVERY_STORE)) request.result.createObjectStore(RECOVERY_STORE);
      if (name === DATABASE && !request.result.objectStoreNames.contains(DRAFT_STORE)) request.result.createObjectStore(DRAFT_STORE);
    };
    request.onsuccess = () => {
      const database = request.result;
      const lookup = database.transaction(STORE).objectStore(STORE).get(KEY);
      lookup.onsuccess = () => { database.close(); resolve(lookup.result as LocalPortfolio | undefined); };
      lookup.onerror = () => { database.close(); reject(lookup.error); };
    };
    request.onerror = () => reject(request.error);
  });
}

function readShadowPortfolio(): LocalPortfolio | undefined {
  if (typeof localStorage === 'undefined') return undefined;
  try {
    const raw = localStorage.getItem(DATABASE) ?? localStorage.getItem(LEGACY_DATABASE);
    return raw ? migratePortfolio(JSON.parse(raw) as LocalPortfolio) : undefined;
  } catch { return undefined; }
}

function readShadowReceipts(): HoldingImportReceipt[] {
  if (typeof localStorage === 'undefined') return [];
  try {
    const raw = localStorage.getItem(`${DATABASE}:${RECEIPTS_KEY}`);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed as HoldingImportReceipt[] : [];
  } catch { return []; }
}

async function readReceiptSidecar(): Promise<HoldingImportReceipt[]> {
  try {
    const database = await openDatabase();
    const value = await new Promise<HoldingImportReceipt[] | undefined>((resolve, reject) => {
      const request = database.transaction(STORE).objectStore(STORE).get(RECEIPTS_KEY);
      request.onsuccess = () => resolve(request.result as HoldingImportReceipt[] | undefined);
      request.onerror = () => reject(request.error);
    });
    database.close();
    return Array.isArray(value) ? value : readShadowReceipts();
  } catch { return readShadowReceipts(); }
}

function mergeReceiptSidecar(portfolio: LocalPortfolio, receipts: HoldingImportReceipt[]): LocalPortfolio {
  const byId = new Map<string, HoldingImportReceipt>();
  [...(portfolio.holdingImportReceipts ?? []), ...receipts].forEach((receipt) => byId.set(receipt.id, receipt));
  return { ...portfolio, holdingImportReceipts: [...byId.values()].sort((left, right) => left.createdAt.localeCompare(right.createdAt)) };
}

function saveShadow(key: string, value: unknown): boolean {
  if (typeof localStorage === 'undefined') return false;
  try {
    localStorage.setItem(key, JSON.stringify(value));
    return true;
  } catch { return false; }
}

function removeShadow(key: string): void {
  if (typeof localStorage === 'undefined') return;
  try { localStorage.removeItem(key); } catch { /* IndexedDB deletion already succeeded. */ }
}

function isNewer(candidate: LocalPortfolio | undefined, reference: LocalPortfolio | undefined): boolean {
  if (!candidate) return false;
  if (!reference) return true;
  return Date.parse(candidate.updatedAt) > Date.parse(reference.updatedAt);
}

export async function loadPortfolio(): Promise<LocalPortfolio> {
  try {
    const receiptSidecar = await readReceiptSidecar();
    const current = await readDatabase(DATABASE).then((value) => value ? migratePortfolio(value) : undefined);
    const shadow = readShadowPortfolio();
    if (isNewer(shadow, current)) {
      const merged = mergeReceiptSidecar(shadow!, receiptSidecar);
      await savePortfolio(merged);
      return merged;
    }
    if (current) return mergeReceiptSidecar(current, receiptSidecar);
    const legacy = await readDatabase(LEGACY_DATABASE);
    if (legacy) {
      const migrated = migratePortfolio(legacy);
      await savePortfolio(migrated);
      return mergeReceiptSidecar(migrated, receiptSidecar);
    }
    return createEmptyPortfolio();
  } catch {
    return mergeReceiptSidecar(readShadowPortfolio() ?? createEmptyPortfolio(), readShadowReceipts());
  }
}

export async function savePortfolio(portfolio: LocalPortfolio): Promise<void> {
  const migrated = migratePortfolio(portfolio);
  let databaseSaved = false;
  try {
    const database = await openDatabase();
    await new Promise<void>((resolve, reject) => {
      const transaction = database.transaction(STORE, 'readwrite');
      const store = transaction.objectStore(STORE);
      store.put(migrated, KEY);
      store.put(migrated.holdingImportReceipts ?? [], RECEIPTS_KEY);
      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error);
    });
    database.close();
    const verified = await readDatabase(DATABASE);
    databaseSaved = verified?.schemaVersion === migrated.schemaVersion
      && verified.updatedAt === migrated.updatedAt
      && (verified.holdingImportReceipts?.length ?? 0) === (migrated.holdingImportReceipts?.length ?? 0);
  } catch { /* The rollback-compatible shadow below remains available. */ }
  const shadowSaved = saveShadow(DATABASE, migrated);
  const receiptShadowSaved = saveShadow(`${DATABASE}:${RECEIPTS_KEY}`, migrated.holdingImportReceipts ?? []);
  if (!databaseSaved && (!shadowSaved || !receiptShadowSaved)) throw new Error('本机账本保存失败，请检查浏览器存储空间或隐私设置后重试');
}

export async function saveRecoveryPoint(portfolio: LocalPortfolio, now: string, reason: RecoveryPoint['reason'] = 'BEFORE_IMPORT'): Promise<RecoveryPoint> {
  const point: RecoveryPoint = {
    id: `recovery-${now.replace(/\D/g, '').slice(0, 17)}`,
    createdAt: now,
    reason,
    previousUpdatedAt: portfolio.updatedAt,
    portfolio: structuredClone(portfolio),
  };
  let databaseSaved = false;
  try {
    const database = await openDatabase();
    await new Promise<void>((resolve, reject) => {
      const store = database.transaction(RECOVERY_STORE, 'readwrite').objectStore(RECOVERY_STORE);
      const request = store.put(point, point.id);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
    database.close();
    databaseSaved = Boolean(await loadRecoveryPoint(point.id));
  } catch { /* Keep the same recovery point in the compatibility shadow. */ }
  const shadowSaved = saveShadow(`${DATABASE}:recovery:${point.id}`, point);
  if (!databaseSaved && !shadowSaved) throw new Error('导入前恢复点保存失败，已取消覆盖操作');
  return point;
}

export async function loadRecoveryPoint(id: string): Promise<RecoveryPoint | null> {
  try {
    const database = await openDatabase();
    const value = await new Promise<RecoveryPoint | undefined>((resolve, reject) => {
      const request = database.transaction(RECOVERY_STORE).objectStore(RECOVERY_STORE).get(id);
      request.onsuccess = () => resolve(request.result as RecoveryPoint | undefined);
      request.onerror = () => reject(request.error);
    });
    database.close();
    return value ?? null;
  } catch {
    const raw = typeof localStorage === 'undefined' ? null : localStorage.getItem(`${DATABASE}:recovery:${id}`);
    return raw ? JSON.parse(raw) as RecoveryPoint : null;
  }
}

export async function saveWorkflowDraft(draft: WorkflowDraft): Promise<void> {
  let databaseSaved = false;
  try {
    const database = await openDatabase();
    await new Promise<void>((resolve, reject) => {
      const request = database.transaction(DRAFT_STORE, 'readwrite').objectStore(DRAFT_STORE).put(draft, draft.id);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
    database.close();
    databaseSaved = true;
  } catch { /* Keep the same draft in the compatibility shadow. */ }
  const shadowSaved = saveShadow(`${DATABASE}:draft:${draft.id}`, draft);
  if (!databaseSaved && !shadowSaved) throw new Error('本机草稿保存失败');
}

export async function loadWorkflowDraft(id: string): Promise<WorkflowDraft | null> {
  try {
    const database = await openDatabase();
    const value = await new Promise<WorkflowDraft | undefined>((resolve, reject) => {
      const request = database.transaction(DRAFT_STORE).objectStore(DRAFT_STORE).get(id);
      request.onsuccess = () => resolve(request.result as WorkflowDraft | undefined);
      request.onerror = () => reject(request.error);
    });
    database.close();
    return value ?? null;
  } catch {
    const raw = localStorage.getItem(`${DATABASE}:draft:${id}`);
    return raw ? JSON.parse(raw) as WorkflowDraft : null;
  }
}

export async function listWorkflowDrafts(prefix: string): Promise<WorkflowDraft[]> {
  try {
    const database = await openDatabase();
    const values = await new Promise<WorkflowDraft[]>((resolve, reject) => {
      const request = database.transaction(DRAFT_STORE).objectStore(DRAFT_STORE).getAll();
      request.onsuccess = () => resolve((request.result as WorkflowDraft[]).filter((draft) => draft.id.startsWith(prefix)));
      request.onerror = () => reject(request.error);
    });
    database.close();
    return values;
  } catch {
    if (typeof localStorage === 'undefined') return [];
    return Object.keys(localStorage)
      .filter((key) => key.startsWith(`${DATABASE}:draft:${prefix}`))
      .flatMap((key) => {
        try { return [JSON.parse(localStorage.getItem(key) ?? '') as WorkflowDraft]; } catch { return []; }
      });
  }
}

export async function discardWorkflowDraft(id: string): Promise<void> {
  try {
    const database = await openDatabase();
    await new Promise<void>((resolve, reject) => {
      const request = database.transaction(DRAFT_STORE, 'readwrite').objectStore(DRAFT_STORE).delete(id);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
    database.close();
  } catch { /* Remove the shadow even when IndexedDB is unavailable. */ }
  removeShadow(`${DATABASE}:draft:${id}`);
}
