import { date, escapeHtml } from './format';
import { confirmedRiskRegime } from './app-state';
import type { LocalPortfolio, PublicSnapshot } from './types';

export type PageId = 'risk' | 'market' | 'asset-cycle' | 'allocation' | 'portfolio' | 'model' | 'data';

export const REGIME = {
  GREEN: { zh: '绿色', copy: '风险预算充足', tone: '#79d6a0' },
  YELLOW: { zh: '黄色', copy: '风险预算保持均衡', tone: '#e8cd68' },
  ORANGE: { zh: '橙色', copy: '风险预算正在收缩', tone: '#ee9b62' },
  RED: { zh: '红色', copy: '优先控制风险预算', tone: '#ef7076' },
  'DATA ERROR': { zh: '数据错误', copy: '暂停新的建议', tone: '#d989ef' },
} as const;

const PRIMARY_NAVIGATION: Array<{ id: PageId; label: string; shortLabel: string; path: string }> = [
  { id: 'risk', label: '总览', shortLabel: '总览', path: 'index.html' },
  { id: 'allocation', label: '目标', shortLabel: '目标', path: 'allocation/index.html' },
  { id: 'portfolio', label: '本月操作', shortLabel: '操作', path: 'portfolio/index.html' },
  { id: 'market', label: '市场', shortLabel: '市场', path: 'market/index.html' },
];

const PROFESSIONAL_NAVIGATION: Array<{ id: PageId; label: string; path: string; note: string }> = [
  { id: 'data', label: '数据与验证', path: 'data/index.html', note: '数据健康、时序、回测与下载' },
  { id: 'model', label: '风险模型', path: 'model/index.html', note: '公式、边界与失效处理' },
  { id: 'asset-cycle', label: '资产周期研究', path: 'asset-cycle/index.html', note: '冻结研究，不参与当前目标和建议' },
];

export interface ShellOptions {
  page: PageId;
  root: string;
  snapshot: PublicSnapshot;
  portfolio: LocalPortfolio;
  content: string;
  dialog: string;
}

export function sparkline(points: Array<{ value: number }>, label: string, width = 720, height = 190): string {
  if (!points.length) return '';
  const values = points.map((point) => point.value);
  const min = Math.min(...values);
  const max = Math.max(...values);
  const span = Math.max(max - min, .0001);
  const path = points.map((point, index) => {
    const x = index / Math.max(1, points.length - 1) * width;
    const y = height - ((point.value - min) / span * (height - 16) + 8);
    return `${index ? 'L' : 'M'}${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(' ');
  return `<svg class="sparkline" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escapeHtml(label)}"><path d="${path}" /></svg>`;
}

export function renderShell(options: ShellOptions): string {
  const { page, root, snapshot, portfolio, content, dialog } = options;
  const regime = REGIME[confirmedRiskRegime(snapshot)] ?? REGIME['DATA ERROR'];
  const lastData = Object.values(snapshot.provenance).map((item) => item.lastDate).filter(Boolean).sort().at(-1) ?? snapshot.meta.signalDate;
  const navigation = PRIMARY_NAVIGATION.map((item) => `<a href="${root}${item.path}"${item.id === page ? ' aria-current="page"' : ''}><span class="nav-full">${item.label}</span><span class="nav-short">${item.shortLabel}</span></a>`).join('');
  const professionalActive = PROFESSIONAL_NAVIGATION.some((item) => item.id === page);
  const professionalNavigation = PROFESSIONAL_NAVIGATION.map((item) => `<a href="${root}${item.path}"${item.id === page ? ' aria-current="page"' : ''}><strong>${item.label}</strong><small>${item.note}</small></a>`).join('');
  const professionalSubnavigation = PROFESSIONAL_NAVIGATION.map((item) => `<a href="${root}${item.path}"${item.id === page ? ' aria-current="page"' : ''}>${item.id === 'data' ? '数据验证' : item.id === 'model' ? '风险模型' : '资产周期'}</a>`).join('');
  const statusClass = snapshot.health.blocking ? 'data-bad' : 'data-good';
  return `<div class="shell" style="--regime:${regime.tone}">
    <header class="topbar"><div class="topbar-inner">
      <a class="brand" href="${root}index.html"><b>资产</b><span>家庭长期投资工作台 · V${escapeHtml(snapshot.meta.webVersion)}</span></a>
      <nav class="page-nav" aria-label="主要页面">${navigation}</nav>
      <div class="top-actions"><a class="data-stamp ${statusClass}" href="${root}data/index.html"><i></i>${snapshot.health.blocking ? '数据异常 · 查看原因' : `数据 ${escapeHtml(lastData)}`}</a><details class="professional-nav${professionalActive ? ' active' : ''}"><summary aria-label="打开专业资料" aria-expanded="false"><span class="professional-label">专业资料</span><span class="professional-short">资料</span><i aria-hidden="true">⌄</i></summary><div><span>专业资料</span>${professionalNavigation}</div></details><button class="quiet-button holdings-record" data-open-portfolio><span>更新持仓</span><small>${portfolio.baseline ? `更新于 ${escapeHtml(portfolio.updatedAt.slice(5, 10))}` : '尚未建立'}</small></button></div>
    </div></header>
    <nav class="mobile-bottom-nav" aria-label="手机主要页面">${navigation}</nav>
    ${professionalActive ? `<div class="professional-subnav-wrap"><nav class="professional-subnav" aria-label="专业资料页面">${professionalSubnavigation}</nav>${page === 'asset-cycle' ? '<span>独立研究 · 不参与目标与建议</span>' : ''}</div>` : ''}
    <main id="main">${content}</main>
    <div id="app-status" class="visually-hidden" role="status" aria-live="polite"></div>
    <footer><p>资产 V${escapeHtml(snapshot.meta.webVersion)} · FRAIS ${escapeHtml(snapshot.meta.strategyVersion)} 风险引擎 · ${escapeHtml(snapshot.policy.adviceNature)}</p><p>范围：七只 ETF 与组合内现金 · 禁止：${snapshot.policy.prohibited.join(' · ')} · <a href="${root}asset-cycle/index.html">资产周期研究</a> · 生成于 ${date(snapshot.meta.generatedAt, true)}</p></footer>
    ${dialog}
  </div>`;
}
